                                ("Amazon auto-generated SKU" if l["method"] == "product-id" else
                                 ("SKU case differs from Sage (Amazon SKU kept)" if l["method"] == "normalised sku" else "")))})
    w_csv("crosswalk.csv", list(cross[0].keys()), cross)

