    with open(path, encoding="utf-8", newline="") as f:
        return f.read()


def feed_rows(content):
    return list(csv.DictReader(io.StringIO(content), delimiter="\t"))


def _header(headers, name):
    for k, v in (headers or {}).items():
        if k.lower() == name.lower():
            return v
    return None

